{
  "operationName": "RegisterUser",
  "query": "mutation RegisterUser($username: String!, $email: String!, $password: String!) { register(username: $username, email: $email, password: $password) { success message } }",
  "variables": {
    "username": "testuser",
    "email": "test@example.com",
    "password": "Test@123456"
  }
}

{
  "operationName": "Login",
  "query": "mutation Login($username: String!, $password: String!, $platform: String!, $deviceName: String!) { login(username: $username, password: $password, platform: $platform, deviceName: $deviceName) { success message accessToken refreshToken user { id username email emailVerified } } }",
  "variables": {
    "username": "testuser",
    "password": "Test@123456",
    "platform": "web",
    "deviceName": "Postman"
  }
}

{
  "operationName": "GetMe",
  "query": "query GetMe { me { id username email emailVerified dateJoined } }"
}

{
  "operationName": "RefreshToken",
  "query": "mutation RefreshToken($refreshToken: String!, $platform: String!) { refreshToken(refreshToken: $refreshToken, platform: $platform) { success message accessToken refreshToken } }",
  "variables": {
    "refreshToken": "{{refreshToken}}",
    "platform": "web"
  }
}

{
  "operationName": "Logout",
  "query": "mutation Logout($refreshToken: String!, $allDevices: Boolean) { logout(refreshToken: $refreshToken, allDevices: $allDevices) { success message count } }",
  "variables": {
    "refreshToken": "{{refreshToken}}",
    "allDevices": false
  }
}

{
  "operationName": "LogoutAll",
  "query": "mutation LogoutAll($refreshToken: String!, $allDevices: Boolean) { logout(refreshToken: $refreshToken, allDevices: $allDevices) { success message count } }",
  "variables": {
    "refreshToken": "{{refreshToken}}",
    "allDevices": true
  }
}

{
  "operationName": "ChangePassword",
  "query": "mutation ChangePassword($oldPassword: String!, $newPassword: String!) { changePassword(oldPassword: $oldPassword, newPassword: $newPassword) { success message } }",
  "variables": {
    "oldPassword": "Test@123456",
    "newPassword": "NewPass@123456"
  }
}

{
  "operationName": "GetMyDevices",
  "query": "query GetMyDevices { myDevices { id deviceName deviceId lastLogin ipAddress } }"
}

{
  "operationName": "RemoveDevice",
  "query": "mutation RemoveDevice($deviceId: String!) { removeDevice(deviceId: $deviceId) { success message } }",
  "variables": {
    "deviceId": "DEVICE_ID_HERE"
  }
}

{
  "operationName": "RemoveOtherDevices",
  "query": "mutation RemoveOtherDevices { removeOtherDevices { success message count } }"
}

{
  "operationName": "GetMySessions",
  "query": "query GetMySessions { mySessions { deviceId platform deviceName ipAddress createdAt } }"
}

{
  "operationName": "VerifyEmail",
  "query": "mutation VerifyEmail($uidb64: String!, $token: String!) { verifyEmail(uidb64: $uidb64, token: $token) { success message } }",
  "variables": {
    "uidb64": "YOUR_UID",
    "token": "YOUR_TOKEN"
  }
}

{
  "operationName": "PasswordResetRequest",
  "query": "mutation PasswordResetRequest($email: String!) { passwordResetRequest(email: $email) { success message } }",
  "variables": {
    "email": "test@example.com"
  }
}

{
  "operationName": "SetNewPassword",
  "query": "mutation SetNewPassword($uidb64: String!, $token: String!, $newPassword: String!) { setNewPassword(uidb64: $uidb64, token: $token, newPassword: $newPassword) { success message } }",
  "variables": {
    "uidb64": "YOUR_UID",
    "token": "YOUR_TOKEN",
    "newPassword": "NewPass@123456"
  }
}

{
  "query": "{ hello }"
}

{
  "operationName": "CreateUpload",
  "query": "mutation CreateUpload($title: String!, $description: String!) { createUpload(title: $title, description: $description) { success message upload { id title description createdAt } } }",
  "variables": {
    "title": "My First Blog",
    "description": "Hello World from GraphQL!"
  }
}

{
  "operationName": "GetAllUploads",
  "query": "query GetAllUploads { allUploads { id title description images createdAt } }"
}

{
  "operationName": "GetUpload",
  "query": "query GetUpload($id: String!) { upload(id: $id) { id title description images createdAt } }",
  "variables": {
    "id": "UPLOAD_ID_HERE"
  }
}

{
  "operationName": "GetMyUploads",
  "query": "query GetMyUploads { myUploads { id title description images createdAt } }"
}

{
  "operationName": "UpdateUpload",
  "query": "mutation UpdateUpload($id: String!, $title: String!, $description: String!) { updateUpload(id: $id, title: $title, description: $description) { success message upload { id title description } } }",
  "variables": {
    "id": "UPLOAD_ID_HERE",
    "title": "Updated Title",
    "description": "Updated Description"
  }
}

{
  "operationName": "DeleteUpload",
  "query": "mutation DeleteUpload($id: String!) { deleteUpload(id: $id) { success message } }",
  "variables": {
    "id": "UPLOAD_ID_HERE"
  }
}
